/* @lc app=leetcode id=1912 lang=kotlin */ class MovieRentingSystem(n: Int, entries: Array<IntArray>, val price: HashMap<Pair<Int, Int>, Int> = HashMap(), val av: HashMap<Int, java.util.TreeSet<Triple<Int, Int, Int>>> = HashMap(), val rented: java.util.TreeSet<Triple<Int, Int, Int>> = java.util.TreeSet(compareBy<Triple<Int, Int, Int>>({ it.first }, { it.second }, { it.third })), val init: Unit = entries.forEach { (s, m, p) -> price[s to m] = p.also { av.getOrPut(m) { java.util.TreeSet(compareBy<Triple<Int, Int, Int>>({ it.first }, { it.second })) }.add(Triple(p, s, m)) } }) { fun search(movie: Int): List<Int> = av[movie]?.take(5)?.map { it.second } ?: listOf() fun rent(shop: Int, movie: Int) { Triple(price[shop to movie]!!, shop, movie).let { t -> av[movie]!!.remove(t).also { rented.add(t) } } } fun drop(shop: Int, movie: Int) { Triple(price[shop to movie]!!, shop, movie).let { t -> rented.remove(t).also { av[movie]!!.add(t) } } } fun report(): List<List<Int>> = rented.take(5).map { listOf(it.second, it.third) } }